<script setup lang="ts">import {onMounted,ref} from 'vue';import {getStudio,getStudioRevisions,restoreStudio,type StudioPayload} from './content-studio-api';const payload=ref<StudioPayload|null>(null),items=ref<any[]>([]),message=ref('');async function load(){payload.value=await getStudio();items.value=(await getStudioRevisions()).items}onMounted(load);async function restore(n:number){if(!confirm(`把草稿恢复到版本 ${n}？公开网站不会立即变化。`))return;await restoreStudio(payload.value!,n);message.value=`已恢复为新草稿，来源版本 ${n}`;await load()}</script><template><div class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">修改历史</p><h1>内容版本与恢复</h1><p>历史记录不可改写。恢复会产生一个新的草稿版本。</p></div><div class="workspace-actions"><a class="button quiet" href="/api/admin/content-studio/export.json">导出全部内容 JSON</a><a class="button quiet" href="/api/admin/content-studio/export.geojson">导出地点 GeoJSON</a></div></div><p v-if="message" class="inline-message">{{message}}</p><div class="history-timeline"><article v-for="item in items"><time>{{new Date(item.created_at).toLocaleString('zh-CN')}}</time><div><strong>{{item.summary}}</strong><p>{{item.object_type}} · {{item.object_id}} · {{item.revision_id}}</p><small>快照 {{item.snapshot_hash.slice(0,12)}}</small></div><button @click="restore(Number(item.revision_no))">恢复为草稿</button></article></div></div></template>
